1	import Fastify from "fastify";
2	import { PrismaClient } from "@prisma/client";
3	import jwt from "jsonwebtoken";
4	import bcrypt from "bcryptjs";
5	import dotenv from "dotenv";
6	
7	dotenv.config();
8	
9	const prisma = new PrismaClient();
10	const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";
11	
12	// Fastify 타입 확장
13	declare module "fastify" {
14	  interface FastifyRequest {
15	    userId?: number;
16	  }
17	}
18	
19	// ──────────────────────────────────────────────────────────────
20	// 유틸리티 함수들
21	// ──────────────────────────────────────────────────────────────
22	
23	// 사용자 응답 포맷터
24	function formatUserResponse(user: any, token: string) {
25	  return {
26	    user: {
27	      username: user.username,
28	      email: user.email,
29	      bio: user.bio,
30	      image: user.image,
31	      token,
32	    },
33	  };
34	}
35	
36	// 아티클 응답 포맷터
37	function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
38	  return {
39	    ...article,
40	    favorited,
41	    favoritesCount,
42	  };
43	}
44	
45	// 인증 미들웨어
46	async function authMiddleware(request: any, reply: any) {
47	  const authHeader = request.headers.authorization;
48	  if (!authHeader) {
49	    reply.code(401).send({ errors: { header: ["인증 토큰이 필요합니다"] } });
50	    return;
51	  }
52	  const parts = authHeader.split(" ");
53	  if (parts[0] !== "Token") {
54	    reply.code(401).send({ errors: { header: ["올바른 형식입니다"] } });
55	    return;
56	  }
57	  try {
58	    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
59	    request.userId = decoded.id;
60	  } catch {
61	    reply.code(401).send({ errors: { header: ["유효하지 않은 토큰입니다"] } });
62	    return;
63	  }
64	}
65	
66	// 슬러그 생성 헬퍼
67	function generateSlug(title: string): string {
68	  return title.toLowerCase().replace(/\s+/g, "-");
69	}
70	
71	// ──────────────────────────────────────────────────────────────
72	// Fastify 앱 초기화
73	// ──────────────────────────────────────────────────────────────
74	
75	const app = Fastify({
76	  logger: true,
77	});
78	
79	// CORS 수동 설정
80	app.addHook("onRequest", async (request: any, reply: any) => {
81	  reply.header("Access-Control-Allow-Origin", "*");
82	  reply.header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
83	  reply.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
84	  if (request.method === "OPTIONS") {
85	    reply.code(204).send();
86	    return;
87	  }
88	});
89	
90	// ──────────────────────────────────────────────────────────────
91	// 사용자 API
92	// ──────────────────────────────────────────────────────────────
93	
94	// 회원가입
95	app.post("/api/users", async (request: any, reply: any) => {
96	  const { username, email, password } = request.body?.user || {};
97	  if (!username || !email || !password) {
98	    const errs: string[] = [];
99	    if (!username) errs.push("username은 필수입니다");
100	    if (!email) errs.push("email은 필수입니다");
101	    if (!password) errs.push("password는 필수입니다");
102	    reply.code(422).send({ errors: { _message: errs } });
103	    return;
104	  }
105	  const existing = await prisma.user.findFirst({
106	    where: { OR: [{ username }, { email }] },
107	  });
108	  if (existing) {
109	    const err: string[] = [];
110	    if (existing.username === username) err.push("username이 이미 사용 중입니다");
111	    if (existing.email === email) err.push("email이 이미 사용 중입니다");
112	    reply.code(422).send({ errors: { _message: err } });
113	    return;
114	  }
115	  const hashedPassword = await bcrypt.hash(password, 10);
116	  const user = await prisma.user.create({
117	    data: { username, email, password: hashedPassword },
118	  });
119	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
120	  reply.code(201).send(formatUserResponse(user, token));
121	  return;
122	});
123	
124	// 로그인
125	app.post("/api/users/login", async (request: any, reply: any) => {
126	  const { email, password } = request.body?.user || {};
127	  const user = await prisma.user.findUnique({ where: { email: email as string } });
128	  if (!user) {
129	    reply.code(422).send({ errors: { email: ["해당 이메일로 등록된 유저가 없습니다"] } });
130	    return;
131	  }
132	  const match = await bcrypt.compare(password, user.password);
133	  if (!match) {
134	    reply.code(422).send({ errors: { password: ["비밀번호가 일치하지 않습니다"] } });
135	    return;
136	  }
137	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
138	  reply.code(200).send(formatUserResponse(user, token));
139	  return;
140	});
141	
142	// 현재 사용자 조회
143	app.get("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
144	  const user = await prisma.user.findUniqueOrThrow({ where: { id: request.userId } });
145	  const token = request.headers.authorization.split(" ")[1];
146	  return formatUserResponse(user, token);
147	});
148	
149	// 사용자 정보 수정
150	app.put("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
151	  const body = request.body?.user || {};
152	  const updates: any = {};
153	  if (body.username !== undefined) updates.username = body.username;
154	  if (body.email !== undefined) updates.email = body.email;
155	  if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
156	  if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
157	  if (body.password !== undefined) updates.password = await bcrypt.hash(body.password, 10);
158	
159	  // 고유성 검증
160	  if (updates.username || updates.email) {
161	    const existing = await prisma.user.findFirst({
162	      where: {
163	        id: { not: request.userId },
164	        OR: [
165	          updates.username !== undefined ? { username: updates.username } : undefined,
166	          updates.email !== undefined ? { email: updates.email } : undefined,
167	        ].filter((e: any) => e !== undefined),
168	      },
169	    });
170	    if (existing) {
171	      const err: string[] = [];
172	      if (updates.username && existing.username === updates.username) err.push("username이 이미 사용 중입니다");
173	      if (updates.email && existing.email === updates.email) err.push("email이 이미 사용 중입니다");
174	      reply.code(422).send({ errors: { _message: err } });
175	      return;
176	    }
177	  }
178	
179	  const user = await prisma.user.update({
180	    where: { id: request.userId },
181	    data: updates,
182	  });
183	  const token = request.headers.authorization.split(" ")[1];
184	  return formatUserResponse(user, token);
185	});
