191	// 프로필 조회
192	app.get("/api/profiles/:username", async (request: any, reply: any) => {
193	  const username = request.params.username as string;
194	  const profile = await prisma.user.findUnique({
195	    where: { username },
196	    select: { id: true, username: true, bio: true, image: true },
197	  });
198	  if (!profile) {
199	    reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
200	    return;
201	  }
202	
203	  // 팔로우 상태 확인 (인증된 경우)
204	  let following = false;
205	  const authHeader = request.headers.authorization;
206	  if (authHeader) {
207	    const parts = authHeader.split(" ");
208	    if (parts[0] === "Token") {
209	      try {
210	        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
211	        const follow = await prisma.follow.findUnique({
212	          where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
213	        });
214	        following = !!follow;
215	      } catch {
216	        following = false;
217	      }
218	    }
219	  }
220	
221	  return { profile: { ...profile, following } };
222	});
223	
224	// 팔로우
225	app.post("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
226	  const username = request.params.username as string;
227	  const target = await prisma.user.findUnique({
228	    where: { username },
229	    select: { id: true },
230	  });
231	  if (!target) {
232	    reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
233	    return;
234	  }
235	  if (target.id === request.userId) {
236	    reply.code(422).send({ errors: { profile: ["자기 자신을 팔로우할 수 없습니다"] } });
237	    return;
238	  }
239	  await prisma.follow.upsert({
240	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
241	    create: { followerId: request.userId, followingId: target.id },
242	    update: {},
243	  });
244	  const profile = await prisma.user.findUnique({
245	    where: { username },
246	    select: { id: true, username: true, bio: true, image: true },
247	  });
248	  const isFollowing = await prisma.follow.findUnique({
249	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
250	  });
251	  return { profile: { ...profile, following: !!isFollowing } };
252	});
253	
254	// 언팔로우
255	app.delete("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
256	  const username = request.params.username as string;
257	  const target = await prisma.user.findUnique({
258	    where: { username },
259	    select: { id: true },
260	  });
261	  if (!target) {
262	    reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
263	    return;
264	  }
265	  await prisma.follow.deleteMany({
266	    where: { followerId: request.userId, followingId: target.id },
267	  });
268	  const profile = await prisma.user.findUnique({
269	    where: { username },
270	    select: { id: true, username: true, bio: true, image: true },
271	  });
272	  const isFollowing = await prisma.follow.findUnique({
273	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
274	  });
275	  return { profile: { ...profile, following: !!isFollowing } };
276	});
