282	// 아티클 생성
283	app.post("/api/articles", { preHandler: authMiddleware }, async (request: any, reply: any) => {
284	  const { title, description, body, tagList = [] } = request.body?.article || {};
285	  if (!title || !description || !body) {
286	    const errs: string[] = [];
287	    if (!title) errs.push("title은 필수입니다");
288	    if (!description) errs.push("description은 필수입니다");
289	    if (!body) errs.push("body는 필수입니다");
290	    reply.code(422).send({ errors: { article: errs } });
291	    return;
292	  }
293	  const slug = generateSlug(title);
294	  const article = await prisma.article.create({
295	    data: {
296	      slug,
297	      title,
298	      description,
299	      body,
300	      author: { connect: { id: request.userId } },
301	      tags: {
302	        create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
303	      },
304	    },
305	    include: {
306	      author: { select: { username: true, bio: true, image: true } },
307	      tags: true,
308	      favorites: true,
309	    },
310	  });
311	  reply.code(201).send({
312	    article: formatArticleResponse(article, false, article.favorites.length),
313	  });
314	  return;
315	});
