317	// 아티클 목록 조회
318	app.get("/api/articles", async (request: any, reply: any) => {
319	  const { author, tag, favorited, limit = "20", offset = "0" } = request.query || {};
320	  const lim = parseInt(limit as string, 10);
321	  const off = parseInt(offset as string, 10);
322	
323	  const where: any = {};
324	  if (author) {
325	    const user = await prisma.user.findUnique({ where: { username: author as string }, select: { id: true } });
326	    if (!user) {
327	      return { articles: [], articlesCount: 0 };
328	    }
329	    where.authorId = user.id;
330	  }
331	  if (tag) {
332	    where.tags = { some: { tag: (tag as string).toLowerCase() } };
333	  }
334	
335	  if (favorited) {
336	    const user = await prisma.user.findUnique({
337	      where: { username: favorited as string },
338	      select: { id: true },
339	    });
340	    if (!user) {
341	      return { articles: [], articlesCount: 0 };
342	    }
343	    const favorites = await prisma.favorite.findMany({
344	      where: { userId: user.id },
345	      select: { articleId: true },
346	    });
347	    const articleIds = favorites.map((f: any) => f.articleId);
348	    if (articleIds.length === 0) {
349	      return { articles: [], articlesCount: 0 };
350	    }
351	    const articles = await prisma.article.findMany({
352	      where: { id: { in: articleIds } },
353	      take: lim,
354	      skip: off,
355	      orderBy: { createdAt: "desc" },
356	      include: { author: { select: { username: true, bio: true, image: true } }, tags: true },
357	    });
358	    return {
359	      articles: articles.map((a: any) => formatArticleResponse(a, false, a.favorites.length)),
360	      articlesCount: articles.length,
361	    };
362	  }
363	
364	  const articles = await prisma.article.findMany({
365	    where,
366	    take: lim,
367	    skip: off,
368	    orderBy: { createdAt: "desc" },
369	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
370	  });
371	  const articlesCount = await prisma.article.count({ where });
372	  return {
373	    articles: articles.map((a: any) => formatArticleResponse(a, false, a.favorites.length)),
374	    articlesCount,
375	  };
376	});
