392	// 아티클 수정
393	app.put("/api/articles/:slug", { preHandler: authMiddleware }, async (request: any, reply: any) => {
394	  const slug = request.params.slug as string;
395	  const article = await prisma.article.findUnique({ where: { slug } });
396	  if (!article) {
397	    reply.code(404).send({ errors: { article: ["not found"] } });
398	    return;
399	  }
400	  if (article.authorId !== request.userId) {
401	    reply.code(401).send({ errors: { article: ["이 아티클을 수정할 권한이 없습니다"] } });
402	    return;
403	  }
404	
405	  const body = request.body?.article || {};
406	  const updates: any = {};
407	  if (body.title !== undefined) updates.title = body.title;
408	  if (body.description !== undefined) updates.description = body.description;
409	  if (body.body !== undefined) updates.body = body.body;
410	
411	  // 태그 업데이트
412	  if (body.tagList !== undefined) {
413	    if (body.tagList === null) {
414	      reply.code(422).send({ errors: { article: ["tagList는 null일 수 없습니다"] } });
415	      return;
416	    }
417	    if (Array.isArray(body.tagList)) {
418	      await prisma.articleTag.deleteMany({ where: { articleId: article.id } });
419	      if (body.tagList.length > 0) {
420	        await prisma.articleTag.createMany({
421	          data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
422	        });
423	      }
424	    }
425	  }
426	
427	  // 슬러그 업데이트
428	  if (updates.title) {
429	    updates.slug = generateSlug(updates.title);
430	  }
431	
432	  const updated = await prisma.article.update({
433	    where: { id: article.id },
434	    data: updates,
435	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
436	  });
437	  return { article: formatArticleResponse(updated, false, updated.favorites.length) };
438	});
