      if (updates.username && existing.username === updates.username) err.push("username이 이미 사용 중입니다");
      if (updates.email && existing.email === updates.email) err.push("email이 이미 사용 중입니다");
      reply.code(422).send({ errors: { _message: err } });
      return;
    }
  }

  const user = await prisma.user.update({
    where: { id: request.userId },
    data: updates,
  });
  const token = request.headers.authorization.split(" ")[1];
  return formatUserResponse(user, token);
});

