1	import Fastify from "fastify";
2	import { PrismaClient } from "@prisma/client";
3	import jwt from "jsonwebtoken";
4	import bcrypt from "bcryptjs";
5	import dotenv from "dotenv";
6	
7	dotenv.config();
8	
9	const prisma = new PrismaClient();
10	const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";
11	
12	// Fastify 타입 확장
13	declare module "fastify" {
14	  interface FastifyRequest {
15	    userId?: number;
16	  }
17	}
18	
19	// ──────────────────────────────────────────────────────────────
20	// 유틸리티 함수들
21	// ──────────────────────────────────────────────────────────────
22	
23	// 사용자 응답 포맷터
24	function formatUserResponse(user: any, token: string) {
25	  return {
26	    user: {
27	      username: user.username,
28	      email: user.email,
29	      bio: user.bio,
30	      image: user.image,
31	      token,
32	    },
33	  };
34	}
35	
36	// 아티클 응답 포맷터
37	function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
38	  return {
39	    ...article,
40	    favorited,
41	    favoritesCount,
42	  };
43	}
44	
45	// 인증 미들웨어
46	async function authMiddleware(request: any, reply: any) {
47	  const authHeader = request.headers.authorization;
48	  if (!authHeader) {
49	    reply.code(401).send({ errors: { token: ["is missing"] } });
50	    return;
51	  }
52	  const parts = authHeader.split(" ");
53	  if (parts[0] !== "Token") {
54	    reply.code(401).send({ errors: { token: ["is invalid"] } });
55	    return;
56	  }
57	  try {
58	    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
59	    request.userId = decoded.id;
60	  } catch {
61	    reply.code(401).send({ errors: { token: ["is invalid"] } });
62	    return;
63	  }
64	}
65	
66	// 슬러그 생성 헬퍼
67	function generateSlug(title: string): string {
68	  return title.toLowerCase().replace(/\s+/g, "-");
69	}
70	
71	// ──────────────────────────────────────────────────────────────
72	// Fastify 앱 초기화
73	// ──────────────────────────────────────────────────────────────
74	
75	const app = Fastify({
76	  logger: true,
77	});
