app.get("/api/profiles/:username", async (request: any, reply: any) => {
  const username = request.params.username as string;
  const profile = await prisma.user.findUnique({
    where: { username },
    select: { id: true, username: true, bio: true, image: true },
  });
  if (!profile) {
    reply.code(404).send({ errors: { profile: ["can't be found"] } });
    return;
  }

  // 팔로우 상태 확인 (인증된 경우)
  let following = false;
  const authHeader = request.headers.authorization;
  if (authHeader) {
    const parts = authHeader.split(" ");
    if (parts[0] === "Token") {
      try {
        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
        const follow = await prisma.follow.findUnique({
          where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
        });
        following = !!follow;
      } catch {
        following = false;
      }
    }
  }

  return { profile: { ...profile, following } };
});

