app.delete("/api/articles/:slug/comments/:id", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const slug = request.params.slug as string;
  const commentId = parseInt(request.params.id as string, 10);
  const comment = await prisma.comment.findUnique({
    where: { id: commentId },
    select: { articleId: true, authorId: true },
  });
  if (!comment) {
    reply.code(404).send({ errors: { comment: ["not found"] } });
    return;
  }
  const article = await prisma.article.findUnique({ where: { id: comment.articleId } });
  if (!article || article.slug !== slug) {
    reply.code(404).send({ errors: { comment: ["not found"] } });
    return;
  }
  if (comment.authorId !== request.userId) {
    reply.code(401).send({ errors: { comment: ["이 코멘트를 삭제할 권한이 없습니다"] } });
    return;
  }
  await prisma.comment.delete({ where: { id: comment.id } });
  reply.code(204).send();
  return;
});

// 즐겨찾기 추가
app.post("/api/articles/:slug/favorite", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const slug = request.params.slug as string;
  const article = await prisma.article.findUnique({
    where: { slug },
    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
  });
  if (!article) {
    reply.code(404).send({ errors: { article: ["not found"] } });
    return;
  }
  await prisma.favorite.create({
    data: { userId: request.userId, articleId: article.id },
  });
